"""Freeze actual v21 changes, including full definitions and anchored proof."""
import json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];RUN=R/'research/source-store/mece-closure-v21-20261011'
def read(p):return json.loads(p.read_text())
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
assert not (RUN/'catalogue-after.json').exists(),'Do not overwrite frozen delta'
d=read(R/'dist/data/operations.json');root=read(R/'data/mece-v21-root-dispositions.json');by={w['id']:w for w in d['works']}
ids=root['added_work_ids']+root['edited_work_ids'];assert len(ids)==len(set(ids))==8
write(RUN/'catalogue-after.json',d)
fields=['id','title','layer','actor_role','object_key','outcome_key','discriminator','definition','includes','excludes']
catalogue=[{k:w.get(k) for k in fields} for w in d['works']]
before=read(RUN/'catalogue-before.json');before_by={w['id']:w for w in before['works']}
sections={w['id']+':proof:'+str(n):r['exact_quote'] for w in [by[i] for i in ids] for n,r in enumerate(w['refs']) if r.get('exact_quote') and not r.get('context_requires_review')}
instructions='''Return JSON only {"rows":[{"id":exact assigned current work ID,"decision":"retain|needs_boundary_edit|needs_source|merge_proposal","work_ids":[current canonical IDs only],"evidence_section_ids":[supplied section IDs only],"reason":Korean,"counterexamples":[Korean],"next_action":Korean}]}. Review all 8 actual changed definitions against the ENTIRE actual 397 catalogue and quoted operative source proofs. All model output remains advisory, never global MECE or human approval. Historic conditional official contracts/statutes are admissible FUNCTION evidence, not universal current law or actual observed UI. Product labels do not create independent work. Fund policy charter formation now generalises Sharia policy; shared fund rule differs from individual investor mandate and separate estate creation. Existing policy amendment needs an effective changed policy; shareholder vote is a specific completion condition, NOT a separate viewpoint work. Verify actor role, authority, initial versus amendment, and policy adoption versus filing registration. Credit facility termination and change requests are generalised existing overdraft request rows. Request submission does not prove rights effect; notice can exercise a contractual option, irreversibility/advance date/conditional revocation are contract conditions. Complete termination extinguishes future committed credit availability while prior loan liabilities survive; partial reduction preserves the relationship. Assess necessity of these two different outcomes without splitting merely by amount. Agent forwards notice; DO NOT invent agent approval or independent legal-effect confirmation. Current new rows cover holder exercise of a contractual right, not every automatic expiry or bank unilateral cancellation. Commitment contract formation is shared and has own signing/effect clause; ownership transfer/participation sale are separate. Compare card limit, internal credit exposure caps, transaction operating caps explicitly; missing generic increases or other actors must remain scoped followups rather than overclaiming same source. Each defect needs actual overlapping direct result or actual missing operative proof; null discriminator or different source example alone is not a fault. Return all assigned IDs and no others.'''
for name,model in [('current-delta-v21-eight','claude-opus-5'),('quality-steward-v21-actual-delta','claude-sonnet-5')]:
    j=dict(id=name,model=model,max_tokens=14000,instructions=instructions+(' Criticise likely wrong screen-building decisions and false closure; do not merely agree with the other model.' if model=='claude-sonnet-5' else ''),input={'catalogue':catalogue,'changed_definitions':[by[i] for i in ids],'prior_definitions':[{k:before_by[i].get(k) for k in fields} for i in ids if i in before_by],'operative_sections':sections,'root_conditions':root['root_corrections']},expected_ids=ids,row_key='id',work_ids=list(by),sections=sections,grounded_section_ids=True)
    write(RUN/'inputs'/(name+'.json'),j)
print(json.dumps({'actual_current':len(by),'actual_delta':len(ids),'catalogue_sha256':hashlib.sha256((RUN/'catalogue-after.json').read_bytes()).hexdigest(),'jobs':2}))
